alter table public.tracks
 add column circuit_id text,
 add column map_key text,
 add column map_path text,
 add column map_source text,
 add column map_scope text not null default 'layout' check(map_scope in ('layout','venue')),
 add column active boolean not null default true,
 add column hidden boolean not null default false,
 add column updated_at timestamptz not null default now();
alter table public.tracks add constraint tracks_safe_path check(map_path is null or (char_length(map_path)<=20000 and map_path ~ '^[MmLlHhVvCcSsQqTtAaZz0-9eE.,+[:space:]-]+$'));
alter table public.tracks add constraint tracks_safe_source check(map_source is null or (char_length(map_source)<=1000 and map_source ~ '^https://[^[:space:]]+$'));
