d":"chuck_cw","name":"Chuckwalla Valley Raceway","variant":"CW","region":"SoCal","circuit_id":"chuckwalla","active":true,"map_key":"chuck","map_source":"https://www.txptrackdays.com/track-maps","map_scope":"layout","hidden":false},{"id":"chuck_ccw","name":"Chuckwalla Valley Raceway","variant":"CCW","region":"SoCal","circuit_id":"chuckwalla","active":true,"map_key":"chuck","map_source":"https://www.txptrackdays.com/track-maps","map_scope":"layout","hidden":false},{"id":"laguna","name":"WeatherTech Raceway Laguna Seca","variant":"Full course","region":"NorCal","circuit_id":"laguna","active":true,"map_key":"laguna","map_source":"https://www.ongridtrack.com/laguna-seca","map_scope":"layout","hidden":false},{"id":"sonoma","name":"Sonoma Raceway","variant":"Layout unspecified","region":"NorCal","circuit_id":"sonoma","active":true,"map_key":"sonoma","map_source":"https://www.ongridtrack.com/sonoma-raceway","map_scope":"venue","hidden":false},{"id":"thunder","name":"Thunderhill Raceway Park","variant":"5 mile · combined","region":"NorCal","circuit_id":"thunderhill","active":true,"map_key":"thunder_combined","map_source":"https://www.trackmasters-racing.com/thunderhill-raceway","map_scope":"venue","hidden":false},{"id":"thunder_east_cyclone","name":"Thunderhill Raceway Park","variant":"East 3 mile · Cyclone · CCW","region":"NorCal","circuit_id":"thunderhill","active":true,"map_key":"thunder_east_cyclone","map_source":"https://www.ongridtrack.com/thunderhill-raceway","map_scope":"layout","hidden":false},{"id":"thunder_east_bypass","name":"Thunderhill Raceway Park","variant":"East 3 mile · Bypass · CCW","region":"NorCal","circuit_id":"thunderhill","active":true,"map_key":"thunder_east_bypass","map_source":"https://www.ongridtrack.com/thunderhill-raceway","map_scope":"layout","hidden":false},{"id":"thunder_west_ccw","name":"Thunderhill Raceway Park","variant":"West 2 mile · CCW","region":"NorCal","circuit_id":"thunderhill","active":true,"map_key":"thunder_west","map_source":"ht