on conflict(id) do nothing;
update public.tracks set circuit_id='circuit_'||md5(lower(btrim(name))||'|'||lower(btrim(region))) where circuit_id is null;
alter table public.tracks alter column circuit_id set not null;

create index tracks_circuit on public.tracks(circuit_id);
-- Existing client versions can still read labels. New fields only expose map metadata.
create or replace view public.leaderboard_tracks with(security_invoker=true) as
 select id,name,variant,region,circuit_id,map_key,map_path,map_source,map_scope,active,hidden from public.tracks;
grant select(id,name,variant,region,circuit_id,map_key,map_path,map_source,map_scope,active,hidden) on public.tracks to anon;
revoke insert,update,delete,truncate,references,trigger on public.tracks from anon,authenticated;
-- A stale client cannot submit to a retired / hidden layout. Existing pending
-- and approved records remain readable and can still be reviewed by staff.
create policy available_layout_submission on public.pending_laps as restrictive
 for insert to authenticated with check(exists(
  select 1 from public.tracks t where t.id=track and t.active and not t.hidden
 ));
-- Only the bounded staff RPC can change the catalog. IDs never change and
-- archival / hiding never deletes or reassigns approved or pending lap records.
create function spinout_private.save_track_layout(p_layout jsonb) returns jsonb
 language plpgsql security definer set search_path='' as $$
declare
 actor text:=spinout_private.member_name();
 saved public.tracks; previous public.tracks;
 layout_id text:=nullif(p_layout->>'id','');
 circuit text:=nullif(p_layout->>'circuit_id','');
 track_name text:=btrim(p_layout->>'name');
 layout_name text:=btrim(p_layout->>'variant');
 region_name text:=btrim(p_layout->>'region');
 source_url text:=nullif(btrim(p_layout->>'map_source'),'');
 trace_path text:=nullif(btrim(p_layout->>'map_path'),'');
 trace_key text:=nullif(btrim(p_layout->>'map_key'),'');
 scope text:=coalesce(p_layout->>'map_scope','layout');
 enabled boolean:=coalesce((p_layout->>'active')::boolean,true);
 hidden_layout boolean:=coalesce((p_layout->>'hidden')::boolean,false);
begin
 if actor is null or not spinout_private.can_moderate() then raise exception 'Moderator required';end if;
 if jsonb_typeof(p_layout) is distinct from 'object' or track_name is null or char_length(track_name) not between 1 and 100 or layout_name is null or char_length(layout_name) not between 1 and 120 or region_name is null or char_length(region_name) not between 1 and 40 then raise exception 'Enter a track name, layout name, and region';end if;
 if scope not in ('layout','venue') then raise exception 'Choose exact layout or venue overview';end if;
 if trace_key is not null and (char_length(trace_key)>100 or trace_key !~ '^[a-zA-Z0-9_-]+$') then raise exception 'Invalid map preset';end if;
 if trace_path is not null and (char_length(trace_path)>20000 or trace_path !~ '^[MmLlHhVvCcSsQqTtAaZz0-9eE.,+[:space:]-]+$') then raise exception 'Invalid map outline';end if;
 if source_url is not null and (char_length(source_url)>1000 or source_url !~ '^https://[^[:space:]]+$') then raise exception 'Map source must be an HTTPS URL';end if;
 if trace_path is not null and source_url is null then raise exception 'Credit a source for your outline';end if;
 perform pg_advisory_xact_lock(hashtextextended('spinout-track-catalog',0));
 if layout_id is not null then
  select * into previous from public.tracks where id=layout_id for update;
  if not found then raise exception 'Layout not found. Refresh the editor.';end if;
  if circuit is distinct from previous.circuit_id then raise exception 'Existing layouts keep their circuit identity';end if;
 else
  layout_id:='layout_'||gen_random_uuid()::text;
 end if;
 if circuit is null then circuit:='circuit_'||gen_random_uuid()::text;end if;
 if exists(select 1 from public.tracks where id<>layout_id and circuit_id=circuit and lower(btrim(variant))=lower(layout_name)) then raise exception 'That layout name already exists in this circuit';end if;
 if exists(select 1 from public.tracks where circuit_id<>circuit and lower(btrim(name))=lower(track_name) and lower(btrim(region))=lower(region_name)) then raise exception 'This track already exists. Add a layout to its existing circuit.';end if;
 -- A track rename / region edit consistently updates every sibling layout.
 update public.tracks set name=track_name,region=region_name,updated_at=now() where circuit_id=circuit;
 insert into public.tracks(id,circuit_id,name,variant,region,map_key,map_path,map_source,map_scope,active,hidden,added_by,created_at)
 values(layout_id,circuit,track_name,layout_name,region_name,trace_key,trace_path,source_url,scope,enabled,hidden_layout,actor,(extract(epoch from now())*1000)::bigint)
 on conflict(id) do update set name=excluded.name,variant=excluded.variant,region=excluded.region,map_key=excluded.map_key,map_path=excluded.map_path,map_source=excluded.map_source,map_scope=excluded.map_scope,active=excluded.active,hidden=excluded.hidden,updated_at=now()
 returning * into saved;
 return to_jsonb(saved);
end $$;
revoke all on function spinout_private.save_track_layout(jsonb) from public,anon,authenticated;
grant execute on function spinout_private.save_track_layout(jsonb) to authenticated;
create function public.spinout_save_track_layout(p_layout jsonb) returns jsonb
 language sql security invoker set search_path='' as $$select spinout_private.save_track_layout(p_layout)$$;
revoke all on function public.spinout_save_track_layout(jsonb) from public,anon,authenticated;
grant execute on function public.spinout_save_track_layout(jsonb) to authenticated;
commit;
